51	export interface WorkspaceHost {
52	  /** What is writing into the active workspace (the switch lock). A move is added here. */
53	  busy(): "recording" | "exporting" | null;
54	  /** Dismiss the capture toast and drop the retained quiet-capture bytes. */
55	  dropPendingCaptures(): void;
56	  /** Re-list every window's library (`library:changed`). */
57	  broadcastLibraryChanged(): void;
58	}
59	
60	let host: WorkspaceHost | null = null;
61	
62	/** The group move running now, if any: it holds the switch lock from its first item to its last. */
63	let moveRun: { stop: boolean } | null = null;
64	
65	/** What locks the switcher right now. */
66	function busyNow(): WorkspaceBusy | null {
67	  return host?.busy() ?? (moveRun ? "moving" : null);
68	}
69	
70	function requireRegistry(): WorkspaceRegistry {
71	  if (!registry) throw new Error("workspaces: not initialized");
72	  return registry;
73	}
74	
75	export function workspaceGate(): WorkspaceGate {
76	  if (!gate) throw new Error("workspaces: not initialized");
77	  return gate;
78	}
79	
80	export async function initWorkspaces(): Promise<void> {
81	  registry = await WorkspaceRegistry.open({
82	    preferencesFile: join(app.getPath("userData"), "preferences.json"),
83	    defaultDirectory: defaultVaultDirectory(),
84	    newId: () => uuidv7(),
85	    onPreferencesWritten: forgetCachedPreferences,
