15	/** Why a registered workspace cannot be used right now. */
16	export type WorkspaceUnavailableReason =
17	  /** The folder is gone: an unplugged drive or a deleted folder. */
18	  | "missing"
19	  /** `.kaipu/workspace/identity.json` exists but cannot be read or parsed. */
20	  | "unreadable"
21	  /** Another workspace's identity is in that folder. */
22	  | "different";
23	
24	/** What locks the switcher (and the "Move to" menus). */
25	export type WorkspaceBusy = "recording" | "exporting" | "moving";
26	
27	/** Why a switch did not happen. */
28	export type WorkspaceSwitchRefusal =
29	  /** A recording or an export is writing into the active workspace (the LOCKED state). */
30	  | "recording"
31	  | "exporting"
32	  /** Items are being moved to another workspace (ADR 0033, decision 14). */
33	  | "moving"
34	  /** The target is not connected. */
35	  | "unavailable"
36	  /** A window said no (Cancel on an unsaved editor) or did not answer in time. */
37	  | "cancelled"
38	  /** The id is not registered. */
39	  | "unknown"
40	  /** preferences.json could not be parsed: nothing is written until the next launch. */
41	  | "read-only";
42	
43	export interface WorkspaceView {
44	  id: string;
45	  name: string;
46	  color: TagColor;
47	  /** One or two characters for the tile. */
48	  initials: string;
49	  path: string;
50	  /** The volume name for a folder under /Volumes, else null (this Mac's disk). */
51	  volume: string | null;
52	  state: "available" | "unavailable";
53	  reason?: WorkspaceUnavailableReason;
54	  /** Local item count, only for the active workspace (null when it was not listed). */
55	  itemCount: number | null;
56	  /**
57	   * The volume the folder is on (`stat.dev`), for an available workspace: a move between two
58	   * workspaces on the same one is instant, otherwise it copies. Null when not connected.
59	   */
60	  device: string | null;
61	}
62	
63	/** `workspaces:list` (and the `workspaces:changed` broadcast). */
64	export interface WorkspacesState {
65	  activeId: string;
66	  generation: number;
67	  /** The one-time "New: workspaces" hint was dismissed (or a workspace was added). */
68	  hintDismissed: boolean;
69	  /** A recording, an export or a move is running: switching is locked. */
70	  busy: WorkspaceBusy | null;
71	  /** preferences.json did not parse: the app runs as before and changes nothing on disk. */
72	  readOnly: boolean;
73	  workspaces: WorkspaceView[];
74	}
