76	export type WorkspaceSwitchResult = { ok: true } | { ok: false; reason: WorkspaceSwitchRefusal };
77	
78	export type WorkspaceAddResult =
79	  | { ok: true; workspace: WorkspaceView }
80	  | { ok: false; reason: "cancelled" | "not-writable" | "read-only" };
81	
82	/** Where "New workspace" would put its folder, and whether that folder can be used. */
83	export type LocationState =
84	  /** Nothing is there: Kaipu creates the folder. */
85	  | "free"
86	  /** An empty folder is already there: Kaipu uses it. */
87	  | "empty"
88	  /** Something is there (a file, or a folder with content): refused, nothing is touched. */
89	  | "not-empty"
90	  /** The folder next to the Default workspace cannot be reached (an unplugged drive). */
91	  | "parent-missing";
92	
93	export interface LocationCheck {
94	  /** The full path of the folder to create, or null when it cannot be worked out. */
95	  path: string | null;
96	  state: LocationState;
97	}
98	
99	export type WorkspaceCreateRefusal =
100	  | "read-only"
101	  | "invalid-name"
102	  | "invalid-color"
103	  | "name-taken"
104	  | "exists"
105	  | "parent-missing"
106	  | "not-writable";
107	
108	/** `workspaces:create`: a new folder next to the Default workspace's, then a switch to it. */
109	export type WorkspaceCreateResult =
110	  | {
111	      ok: true;
112	      workspace: WorkspaceView;
113	      /** Creating switches like any other switch; a recording running refuses it. */
114	      switchResult: WorkspaceSwitchResult;
115	    }
116	  | { ok: false; reason: WorkspaceCreateRefusal };
117	
118	export interface WorkspaceEditRequest {
119	  id: string;
120	  name?: string;
121	  color?: TagColor;
122	}
123	
124	export type WorkspaceEditRefusal =
125	  | "read-only"
126	  | "unknown"
127	  | "invalid-name"
128	  | "invalid-color"
129	  | "name-taken"
130	  | "not-writable";
