144	
145	/**
146	 * Why "Change folder…" (relocate) did not point a workspace at the picked folder. Relocating
147	 * never moves or copies files: it only says where the workspace now lives.
148	 */
149	export type WorkspaceRelocateRefusal =
150	  | "read-only"
151	  | "unknown"
152	  /** The user closed the folder picker, or a window answered Cancel to an unsaved editor. */
153	  | "cancelled"
154	  /** A recording or an export is writing into the active workspace (the LOCKED state). */
155	  | "recording"
156	  | "exporting"
157	  /** A group move is running (part 2): a folder cannot change under it. */
158	  | "moving"
159	  /** The picked path is not a folder. */
160	  | "not-a-folder"
